python.delete_order.py:
import os
import json
import boto3
from botocore.exceptions import ClientError

logger = boto3.getLogger()

def handler(event, context):
    table_name = os.environ.get("TABLE_NAME")
    if not table_name:
        raise RuntimeError("Missing required environment variable: TABLE_NAME")

    dynamodb = boto3.resource("dynamodb")
    table = dynamodb.Table(table_name)

    order_id = event.get("order_id")
    if not order_id:
        return {
            "statusCode": 400,
            "headers": {"Content-Type": "application/json"},
            "body": json.dumps({"error": "order_id is required"})
        }

    try:
        response = table.delete_item(
            Key={"order_id": order_id}
        )
        return {
            "statusCode": 200,
            "headers": {"Content-Type": "application/json"},
            "body": json.dumps({"message": "Order deleted successfully"})
        }
    except ClientError as e:
        logger.error(e)
        return {
            "statusCode": 500,
            "headers": {"Content-Type": "application/json"},
            "body": json.dumps({"error": "Internal server error"})
        }

