import os
import boto3
from botocore.exceptions import ClientError

def lambda_handler(event, context):
    table_name = os.environ.get("TABLE_NAME")
    if not table_name:
        raise RuntimeError("Missing required environment variable: TABLE_NAME")

    dynamodb = boto3.resource("dynamodb")
    table = dynamodb.Table(table_name)

    order_id = event.get("order_id")
    if not order_id:
        return {
            "statusCode": 400,
            "headers": {"Content-Type": "application/json"},
            "body": json.dumps({"error": "order_id is required"})
        }

    status = event.get("status")
    if not status:
        return {
            "statusCode": 400,
            "headers": {"Content-Type": "application/json"},
            "body": json.dumps({"error": "status is required"})
        }

    try:
        response = table.update_item(
            Key={"order_id": order_id},
            UpdateExpression="set status = :s",
            ExpressionAttributeValues={":s": status},
            ReturnValues="UPDATED_NEW"
        )
        return {
            "statusCode": 200,
            "headers": {"Content-Type": "application/json"},
            "body": json.dumps(response.get("Attributes"), default=str)
        }
    except ClientError as e:
        return {
            "statusCode": 500,
            "headers": {"Content-Type": "application/json"},
            "body": json.dumps({"error": "Internal server error"})
        }

