import json
import boto3
from botocore.exceptions import ClientError

sqs_client = boto3.client('sqs', region_name=os.environ['region'])
dynamodb_client = boto3.client('dynamodb', region_name=os.environ['region'])

def handler(event, context):
    try:
        execution_id = event['execution_id']
        email = event['email']
        prompt = event['prompt']
        s3_file_path = event['s3_file_path']
        technical_analysis = event['technical_analysis']

        # Put item in DynamoDB
        dynamodb_client.put_item(
            TableName=os.environ['TABLE_NAME'],
            Item={
                'execution_id': {'S': execution_id},
                'SK': {'S': 'REPORT'},
                'email': {'S': email},
                'prompt': {'S': prompt},
                'image': {'S': s3_file_path},
               'result': technical_analysis
            }
        )

        # Send message to SQS
        response = sqs_client.send_message(
            QueueUrl=os.environ['queue_url'],
            MessageBody=json.dumps(event)
        )

        return {
           'statusCode': 200,
            'headers': {
                'Content-Type': 'application/json'
            },
            'body': json.dumps({
               'status': 'SUCCESS',
                'db_item_id': execution_id,
               'sqs_message_id': response['MessageId']
            })
        }

    except ClientError as e:
        logging.error(e)
        return {
           'statusCode': 500,
            'headers': {
                'Content-Type': 'application/json'
            },
            'body': json.dumps({'error': 'Internal Server Error'})
        }

    except KeyError as e:
        logging.error(e)
        return {
           'statusCode': 400,
            'headers': {
                'Content-Type': 'application/json'
            },
            'body': json.dumps({'error': 'Invalid input'})
        }

    except Exception as e:
        logging.error(e)
        return {
           'statusCode': 500,
            'headers': {
                'Content-Type': 'application/json'
            },
            'body': json.dumps({'error': 'Internal Server Error'})
        }

