import os
import boto3
from botocore.exceptions import ClientError

def handler(event, context):
    s3_client = boto3.client('s3', region_name=os.environ['AWS_REGION'])
    bucket_name = os.environ['s3_bucket_name']

    try:
        response = s3_client.create_presigned_post(
            Bucket=bucket_name,
            Key=event['key'],
            Fields={
                'acl': 'public-read'
            },
            Conditions=[
                {"acl": 'public-read'}
            ],
            ExpiresIn=3600
        )
        return {
           'statusCode': 200,
            'headers': {
                'Content-Type': 'application/json'
            },
            'body': json.dumps(response, default=str)
        }
    except ClientError as e:
        logging.error(e)
        return {
           'statusCode': 500,
            'headers': {
                'Content-Type': 'application/json'
            },
            'body': json.dumps({'error': 'Failed to create presigned URL for S3 upload'})
        }

