python.report_adapter.py:
import json
import os
import boto3
from botocore.exceptions import ClientError

s3_client = boto3.client('s3')
dynamodb_client = boto3.client('dynamodb')
sqs_client = boto3.client('sqs')

def lambda_handler(event, context):
    try:
        execution_id = event['execution_id']
        email = event['email']
        prompt = event['prompt']
        s3_file_path = event['s3_file_path']
        technical_analysis = event['technical_analysis']

        table_name = os.environ['TABLE_NAME']
        queue_url = os.environ['SQS_PDF_MAIL_QUEUE_URL']

        dynamodb_item = {
            'PK': {'S': execution_id},
            'SK': {'S': 'REPORT'},
            'email': {'S': email},
            'prompt': {'S': prompt},
            'image': {'S': s3_file_path},
           'result': technical_analysis
        }

        dynamodb_client.put_item(
            TableName=table_name,
            Item=dynamodb_item
        )

        sqs_client.send_message(
            QueueUrl=queue_url,
            MessageBody=json.dumps(event)
        )

        return {
           'statusCode': 200,
            'headers': {
                'Content-Type': 'application/json'
            },
            'body': json.dumps({
               'status': 'SUCCESS',
                'db_item_id': execution_id,
               'sqs_message_id': sqs_client.send_message(QueueUrl=queue_url, MessageBody=json.dumps(event))['MessageId']
            })
        }

    except ClientError as e:
        logging.error(e)
        return {
           'statusCode': 500,
            'headers': {
                'Content-Type': 'application/json'
            },
            'body': json.dumps({'error': 'Internal Server Error'})
        }

    except KeyError as e:
        logging.error(e)
        return {
           'statusCode': 400,
            'headers': {
                'Content-Type': 'application/json'
            },
            'body': json.dumps({'error': 'Bad Request'})
        }

    except Exception as e:
        logging.error(e)
        return {
           'statusCode': 500,
            'headers': {
                'Content-Type': 'application/json'
            },
            'body': json.dumps({'error': 'Internal Server Error'})
        }
